import sys
def is_prime(n):
    if n < 2: return False
    i = 2
    while i * i <= n:
        if n % i == 0: return False
        i += 1
    return True
def prime_bus(n):
    return "yes" if is_prime(n) else "no"
if __name__ == "__main__":
    n = int(sys.stdin.readline())
    print(prime_bus(n))

